-- ============================================================================
-- seed_kenya_questions_batch5.sql
-- 57 more questions, mostly hard and medium, aimed at the thinnest categories
-- (Swahili & Sheng, Kenyan Food & Culture, Safaricom & Tech, Matatus & Transport,
-- Music & Entertainment) plus extra hard questions in History, Geography, Sports
-- and Wildlife. Each has a "Did you know?" line.
-- Run AFTER 024_content_quality.sql. Safe to re-run (skips existing question text).
-- IMPORTANT: have a Kenyan reviewer check every fact (see batch5_review.md) before release.
-- ============================================================================

insert into public.categories (name)
select c.name from (values ($q$General Knowledge$q$), ($q$Kenyan Food & Culture$q$), ($q$Kenyan Geography$q$), ($q$Kenyan History$q$), ($q$Kenyan Sports$q$), ($q$Kenyan Wildlife & Culture$q$), ($q$Matatus & Transport$q$), ($q$Music & Entertainment$q$), ($q$Safaricom & Tech$q$), ($q$Swahili & Sheng$q$)) as c(name)
where not exists (select 1 from public.categories x where x.name = c.name);

insert into public.questions
  (category_id, question_text, option_a, option_b, option_c, option_d, correct_option, difficulty, did_you_know)
select (select id from public.categories where name = v.cat limit 1),
       v.question_text, v.a, v.b, v.c, v.d, v.correct, v.difficulty, v.fact
from (values
  ($q$Swahili & Sheng$q$, $q$Which day of the week is "Alhamisi" in Swahili?$q$, $q$Friday$q$, $q$Thursday$q$, $q$Sunday$q$, $q$Wednesday$q$, 'b', 'medium', $q$"Alhamisi" comes from the Arabic "al-khamis", which means "the fifth".$q$),
  ($q$Swahili & Sheng$q$, $q$What does the proverb "Haba na haba hujaza kibaba" teach?$q$, $q$Never share your food$q$, $q$Rain follows the sun$q$, $q$Hard work is never rewarded$q$, $q$Small amounts add up over time$q$, 'd', 'medium', $q$A "kibaba" is a small measure. Little by little, it fills up.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, what is a "msee"?$q$, $q$A teacher$q$, $q$A house$q$, $q$A guy$q$, $q$A bus$q$, 'c', 'medium', $q$"Msee" is one of the most common Sheng words for a man or a person.$q$),
  ($q$Swahili & Sheng$q$, $q$What does the Sheng word "ngori" mean?$q$, $q$Difficult$q$, $q$Funny$q$, $q$Expensive$q$, $q$Fast$q$, 'a', 'hard', $q$Sheng speakers say something is "ngori" when it is tough or hard.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, how much money is "mbao"?$q$, $q$10 shillings$q$, $q$50 shillings$q$, $q$20 shillings$q$, $q$100 shillings$q$, 'c', 'medium', $q$"Mbao" literally means wooden planks in Swahili. In Sheng it became slang for KSh 20.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, how much money is "ngiri"?$q$, $q$1,000 shillings$q$, $q$500 shillings$q$, $q$100 shillings$q$, $q$10,000 shillings$q$, 'a', 'hard', $q$"Ngiri" is the Kikuyu word for one thousand.$q$),
  ($q$Swahili & Sheng$q$, $q$What is the Swahili word for "bridge"?$q$, $q$Barabara$q$, $q$Mlima$q$, $q$Daraja$q$, $q$Mto$q$, 'c', 'hard', $q$"Barabara" is road, "mto" is river and "mlima" is mountain.$q$),
  ($q$Swahili & Sheng$q$, $q$In Swahili, "mwezi" can mean both "month" and which heavenly body?$q$, $q$The sun$q$, $q$A cloud$q$, $q$A star$q$, $q$The moon$q$, 'd', 'medium', $q$Months were once counted by the moon, so one word does both jobs.$q$),
  ($q$Swahili & Sheng$q$, $q$What number is "arobaini" in Swahili?$q$, $q$4$q$, $q$40$q$, $q$14$q$, $q$400$q$, 'b', 'medium', $q$"Nne" is 4, "kumi na nne" is 14 and "arobaini" is 40.$q$),
  ($q$Swahili & Sheng$q$, $q$What does the Swahili word "maktaba" mean?$q$, $q$School$q$, $q$Hospital$q$, $q$Library$q$, $q$Market$q$, 'c', 'hard', $q$"Maktaba" comes from Arabic. A market is "soko" and a school is "shule".$q$),
  ($q$Kenyan Food & Culture$q$, $q$Mukimo, a Kenyan favourite, is made by mashing potatoes with what?$q$, $q$Millet and milk$q$, $q$Maize, beans or peas, and greens$q$, $q$Cassava and fish$q$, $q$Rice and coconut$q$, 'b', 'medium', $q$Mukimo comes from the Kikuyu community and is often served with stew.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Omena, a popular protein in western Kenya, is a small fish from which lake?$q$, $q$Lake Baringo$q$, $q$Lake Victoria$q$, $q$Lake Turkana$q$, $q$Lake Naivasha$q$, 'b', 'medium', $q$Omena is also known as dagaa and is dried or fried whole.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Mahamri, the Swahili coast's version of the mandazi, is flavoured with what?$q$, $q$Peanut butter and chilli$q$, $q$Milk and cinnamon$q$, $q$Coconut milk and cardamom$q$, $q$Honey and sesame$q$, 'c', 'medium', $q$The coconut milk makes mahamri softer and richer than a plain mandazi.$q$),
  ($q$Kenyan Food & Culture$q$, $q$What is kachumbari?$q$, $q$A sweet maize drink$q$, $q$A fresh tomato and onion salad$q$, $q$A fried fish stew$q$, $q$A spiced rice dish$q$, 'b', 'medium', $q$It is usually served with nyama choma and pilau.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Pilau, a spiced rice dish, is especially popular in which part of Kenya?$q$, $q$The highlands$q$, $q$The north-east desert$q$, $q$The Rift Valley floor$q$, $q$The coast$q$, 'd', 'medium', $q$Pilau reflects the Swahili coast's trade links with Arabia and India.$q$),
  ($q$Kenyan Food & Culture$q$, $q$In Dholuo, what is "kuon"?$q$, $q$Sweet potato$q$, $q$Milk$q$, $q$Fish stew$q$, $q$Ugali$q$, 'd', 'hard', $q$The Luo traditionally eat kuon with fish from Lake Victoria.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Managu, a popular leafy vegetable, is known in English as what?$q$, $q$African nightshade$q$, $q$Spinach$q$, $q$Cabbage$q$, $q$Kale$q$, 'a', 'hard', $q$Managu is rich in iron and often cooked with milk or groundnuts.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Terere, a leafy vegetable eaten in Kenya, is known in English as what?$q$, $q$Amaranth$q$, $q$Cowpea leaves$q$, $q$Pumpkin leaves$q$, $q$Collard greens$q$, 'a', 'hard', $q$Terere is also called mchicha at the coast and in Tanzania.$q$),
  ($q$Safaricom & Tech$q$, $q$In which year did Safaricom launch M-Pesa?$q$, $q$2007$q$, $q$2003$q$, $q$2010$q$, $q$2000$q$, 'a', 'medium', $q$M-Pesa started as a pilot with Vodafone and went national in 2007.$q$),
  ($q$Safaricom & Tech$q$, $q$In M-Pesa, what does the "M" stand for?$q$, $q$Market$q$, $q$Member$q$, $q$Money$q$, $q$Mobile$q$, 'd', 'medium', $q$"Pesa" is the Swahili word for money, so M-Pesa means "mobile money".$q$),
  ($q$Safaricom & Tech$q$, $q$Which two organisations backed the original M-Pesa pilot project?$q$, $q$Google and Microsoft$q$, $q$The World Bank and the IMF$q$, $q$Equity Bank and KCB$q$, $q$Vodafone and the UK's DFID$q$, 'd', 'hard', $q$The pilot received support from Britain's Department for International Development.$q$),
  ($q$Safaricom & Tech$q$, $q$What does "Ushahidi", the name of Kenya's famous crisis-mapping platform, mean in Swahili?$q$, $q$Map$q$, $q$Testimony$q$, $q$Journey$q$, $q$Freedom$q$, 'b', 'hard', $q$Ushahidi was built in Kenya and is now used around the world.$q$),
  ($q$Safaricom & Tech$q$, $q$Ushahidi was first built to map reports of violence after which Kenyan event?$q$, $q$The 2007 general election$q$, $q$The 1998 embassy bombing$q$, $q$The 2013 Westgate attack$q$, $q$The 1982 coup attempt$q$, 'a', 'hard', $q$The tool let ordinary people send in reports by text and web.$q$),
  ($q$Safaricom & Tech$q$, $q$Which city is nicknamed "Silicon Savannah"?$q$, $q$Nairobi$q$, $q$Mombasa$q$, $q$Kisumu$q$, $q$Nakuru$q$, 'a', 'medium', $q$The nickname comes from the city's many tech start-ups and innovation hubs.$q$),
  ($q$Safaricom & Tech$q$, $q$What are "Bonga Points" on Safaricom?$q$, $q$A savings account$q$, $q$Data bundles$q$, $q$Airtime loans$q$, $q$Loyalty rewards$q$, 'd', 'medium', $q$Customers earn them as they use Safaricom services and can redeem them for rewards.$q$),
  ($q$Safaricom & Tech$q$, $q$Fuliza is an M-Pesa overdraft. What does the Swahili word "fuliza" mean?$q$, $q$To save$q$, $q$To return$q$, $q$To keep going$q$, $q$To borrow$q$, 'c', 'hard', $q$Fuliza was launched in 2019 and lets you complete a payment even when you are short.$q$),
  ($q$Matatus & Transport$q$, $q$The name "boda boda" comes from which English phrase?$q$, $q$Body on board$q$, $q$Bike on bike$q$, $q$Back to back$q$, $q$Border to border$q$, 'd', 'hard', $q$Cyclists first ferried people between the Kenya and Uganda border posts.$q$),
  ($q$Matatus & Transport$q$, $q$The word "matatu" is linked to which Swahili number?$q$, $q$Five (tano)$q$, $q$Seven (saba)$q$, $q$Ten (kumi)$q$, $q$Three (tatu)$q$, 'd', 'medium', $q$Early matatu fares were about 30 cents, and "tatu" means three.$q$),
  ($q$Matatus & Transport$q$, $q$What is the name of the SGR passenger train between Nairobi and Mombasa?$q$, $q$Madaraka Express$q$, $q$Lunatic Express$q$, $q$Safari Express$q$, $q$Rift Valley Flyer$q$, 'a', 'medium', $q$It began running on 31 May 2017, Madaraka Day.$q$),
  ($q$Matatus & Transport$q$, $q$Which nickname was given to the colonial railway from Mombasa to Lake Victoria?$q$, $q$The Madaraka Express$q$, $q$The Lunatic Express$q$, $q$The Coast Runner$q$, $q$The Iron Snake$q$, 'b', 'hard', $q$Critics thought the costly railway was a crazy idea. It reached Kisumu in 1901.$q$),
  ($q$Matatus & Transport$q$, $q$Kenya Airways uses which well-known slogan?$q$, $q$Africa's Wings$q$, $q$The Safari Skyway$q$, $q$Fly the Rift$q$, $q$The Pride of Africa$q$, 'd', 'medium', $q$Kenya Airways flies from its hub at Jomo Kenyatta International Airport in Nairobi.$q$),
  ($q$Matatus & Transport$q$, $q$The Likoni Ferry connects Mombasa Island to which area?$q$, $q$Diani Beach$q$, $q$Lamu Island$q$, $q$Malindi$q$, $q$The south mainland$q$, 'd', 'medium', $q$Thousands of people cross the channel on the ferry every day.$q$),
  ($q$Matatus & Transport$q$, $q$In Sheng, what is a "nganya"?$q$, $q$A decorated matatu$q$, $q$A bus conductor$q$, $q$A boda boda rider$q$, $q$A bus stage$q$, 'a', 'hard', $q$Nganyas are known for bright graffiti, loud music and screens.$q$),
  ($q$Matatus & Transport$q$, $q$In matatu slang, what is a "makanga"?$q$, $q$The conductor$q$, $q$The passenger$q$, $q$The traffic officer$q$, $q$The driver$q$, 'a', 'medium', $q$The makanga collects fares and calls out for passengers.$q$),
  ($q$Matatus & Transport$q$, $q$The 2003 rules on seat belts and speed governors in matatus are named after which minister?$q$, $q$Raila Odinga$q$, $q$Kenneth Matiba$q$, $q$Mwai Kibaki$q$, $q$John Michuki$q$, 'd', 'hard', $q$The "Michuki Rules" also required a yellow stripe along the matatu body.$q$),
  ($q$Music & Entertainment$q$, $q$Benga, one of Kenya's best-known music styles, grew out of which community?$q$, $q$The Kamba$q$, $q$The Maasai$q$, $q$The Luo$q$, $q$The Mijikenda$q$, 'c', 'medium', $q$Benga is known for fast, melodic guitar lines.$q$),
  ($q$Music & Entertainment$q$, $q$The nyatiti, a traditional eight-stringed lyre, belongs to which community?$q$, $q$The Kikuyu$q$, $q$The Luo$q$, $q$The Turkana$q$, $q$The Giriama$q$, 'b', 'hard', $q$The player often wears bells on the ankles and keeps the beat with them.$q$),
  ($q$Music & Entertainment$q$, $q$Which 2012 Kenyan film by David "Tosh" Gitonga was submitted for the Oscars' Best Foreign Language Film?$q$, $q$Kati Kati$q$, $q$Supa Modo$q$, $q$Rafiki$q$, $q$Nairobi Half Life$q$, 'd', 'hard', $q$The film follows a young man who moves to Nairobi to become an actor.$q$),
  ($q$Music & Entertainment$q$, $q$Which 2018 Kenyan film by Wanuri Kahiu was the first from Kenya selected for the Cannes Film Festival?$q$, $q$Supa Modo$q$, $q$Nairobi Half Life$q$, $q$Soul Boy$q$, $q$Rafiki$q$, 'd', 'hard', $q$It was shown in the Un Certain Regard section.$q$),
  ($q$Music & Entertainment$q$, $q$Genge, a Kenyan music genre of the 2000s, blends hip-hop with rhymes in which language?$q$, $q$Kamba$q$, $q$Dholuo$q$, $q$Sheng$q$, $q$Kikuyu$q$, 'c', 'medium', $q$Genge helped bring Sheng into mainstream radio.$q$),
  ($q$Music & Entertainment$q$, $q$"Unbwogable" by Gidi Gidi Maji Maji became an anthem of which 2002 campaign?$q$, $q$The Safari Rally$q$, $q$The Vision 2030 launch$q$, $q$The NARC election campaign$q$, $q$The Harambee Stars qualifiers$q$, 'c', 'hard', $q$The song title means "cannot be shaken" and was played at rallies across the country.$q$),
  ($q$Kenyan History$q$, $q$In which year was the failed coup attempt against President Daniel arap Moi?$q$, $q$1991$q$, $q$1978$q$, $q$1982$q$, $q$1969$q$, 'c', 'hard', $q$It happened on 1 August 1982 and was put down within hours.$q$),
  ($q$Kenyan History$q$, $q$In which city were the Lancaster House Conferences on Kenya's independence held?$q$, $q$Dar es Salaam$q$, $q$Geneva$q$, $q$London$q$, $q$Nairobi$q$, 'c', 'medium', $q$The talks in 1960, 1962 and 1963 set the path to independence.$q$),
  ($q$Kenyan History$q$, $q$In which year did Wangari Maathai found the Green Belt Movement?$q$, $q$1977$q$, $q$1992$q$, $q$1963$q$, $q$1985$q$, 'a', 'hard', $q$The movement has planted millions of trees across Kenya.$q$),
  ($q$Kenyan Geography$q$, $q$Lake Bogoria in the Rift Valley is famous for which feature?$q$, $q$Hot springs and geysers$q$, $q$Waterfalls$q$, $q$Coral reefs$q$, $q$Floating islands$q$, 'a', 'medium', $q$Thousands of flamingos feed along its shore.$q$),
  ($q$Kenyan Geography$q$, $q$Which river do wildebeest cross in the Maasai Mara during the Great Migration?$q$, $q$The Nzoia River$q$, $q$The Tana River$q$, $q$The Athi River$q$, $q$The Mara River$q$, 'd', 'medium', $q$Crocodiles wait in the river as the herds cross.$q$),
  ($q$Kenyan Sports$q$, $q$What was Eliud Kipchoge's time in the 2019 INEOS 1:59 Challenge in Vienna?$q$, $q$1:59:40$q$, $q$1:58:30$q$, $q$2:00:25$q$, $q$1:59:59$q$, 'a', 'hard', $q$It was not an official record because pacers rotated in and out.$q$),
  ($q$Kenyan Sports$q$, $q$Samuel Wanjiru became the first Kenyan to win Olympic marathon gold at which Games?$q$, $q$Sydney 2000$q$, $q$London 2012$q$, $q$Athens 2004$q$, $q$Beijing 2008$q$, 'd', 'medium', $q$He won in an Olympic record time.$q$),
  ($q$Kenyan Sports$q$, $q$In which event has Faith Kipyegon won three Olympic gold medals?$q$, $q$Marathon$q$, $q$1500 metres$q$, $q$5000 metres$q$, $q$800 metres$q$, 'b', 'hard', $q$She won at Rio 2016, Tokyo 2020 and Paris 2024.$q$),
  ($q$Kenyan Sports$q$, $q$Who won the 3000 metres steeplechase gold for Kenya at Mexico City 1968?$q$, $q$Amos Biwott$q$, $q$Kipchoge Keino$q$, $q$Naftali Temu$q$, $q$Ben Jipcho$q$, 'a', 'hard', $q$Kenya won three golds in 1968: Temu, Keino and Biwott.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Where do the world's last two northern white rhinos live?$q$, $q$Maasai Mara$q$, $q$Nairobi National Park$q$, $q$Tsavo East$q$, $q$Ol Pejeta Conservancy$q$, 'd', 'hard', $q$They are two females, Najin and Fatu, guarded around the clock.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which is Kenya's largest national park?$q$, $q$Nairobi National Park$q$, $q$Tsavo East$q$, $q$Amboseli$q$, $q$Maasai Mara$q$, 'b', 'medium', $q$Tsavo East covers nearly 14,000 square kilometres.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which famous Marsabit elephant was put under round-the-clock armed guard by President Kenyatta?$q$, $q$Ahmed$q$, $q$Mountain Bull$q$, $q$Satao$q$, $q$Tim$q$, 'a', 'hard', $q$Ahmed was known for his huge tusks. A statue of him stands at the National Museum in Nairobi.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which Kenyan author wrote the novel "A Grain of Wheat" (1967)?$q$, $q$Binyavanga Wainaina$q$, $q$Grace Ogot$q$, $q$Meja Mwangi$q$, $q$Ngũgĩ wa Thiong'o$q$, 'd', 'medium', $q$The novel is set in the days leading up to Kenya's independence.$q$),
  ($q$General Knowledge$q$, $q$What is the capital of Burkina Faso?$q$, $q$Niamey$q$, $q$Bamako$q$, $q$Accra$q$, $q$Ouagadougou$q$, 'd', 'hard', $q$Ouagadougou is known for its film festival, FESPACO.$q$),
  ($q$General Knowledge$q$, $q$Which chemical element has the symbol "W"?$q$, $q$Water$q$, $q$Wolframite$q$, $q$Vanadium$q$, $q$Tungsten$q$, 'd', 'hard', $q$The symbol comes from "wolfram", the element's old name.$q$),
  ($q$General Knowledge$q$, $q$Which artist painted "Guernica"?$q$, $q$Pablo Picasso$q$, $q$Joan Miro$q$, $q$Henri Matisse$q$, $q$Salvador Dali$q$, 'a', 'medium', $q$Picasso painted it in 1937 after the bombing of a Spanish town.$q$)
) as v(cat, question_text, a, b, c, d, correct, difficulty, fact)
where not exists (select 1 from public.questions q where q.question_text = v.question_text);
